content:
Save this as `index.html` and open it in a modern browser. It uses only the Three.js core ES module from cdnjs and includes custom orbit, zoom, touch, click, and camera controls.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Dawnbreaker Kite Shield</title>

  <style>
    :root {
      color-scheme: dark;
      --gold: #e3b66d;
      --cyan: #76e7df;
      --panel: rgba(7, 16, 22, 0.72);
      --border: rgba(151, 211, 205, 0.25);
    }

    * {
      box-sizing: border-box;
    }

    html,
    body {
      width: 100%;
      height: 100%;
      margin: 0;
      overflow: hidden;
      background: #071018;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
        "Segoe UI", sans-serif;
    }

    canvas {
      display: block;
      width: 100%;
      height: 100%;
      outline: none;
      touch-action: none;
      cursor: grab;
    }

    canvas.dragging {
      cursor: grabbing;
    }

    canvas:hover {
      cursor: pointer;
    }

    .vignette {
      position: fixed;
      inset: 0;
      pointer-events: none;
      background:
        radial-gradient(circle at 50% 45%, transparent 35%, rgba(1, 5, 8, 0.42) 100%),
        linear-gradient(180deg, rgba(4, 10, 15, 0.22), transparent 25%, transparent 75%, rgba(4, 10, 15, 0.45));
      z-index: 2;
    }

    .hud {
      position: fixed;
      inset: 0;
      z-index: 3;
      pointer-events: none;
      color: #eef8f5;
    }

    .title-block {
      position: absolute;
      top: clamp(24px, 5vw, 64px);
      left: clamp(24px, 5vw, 72px);
      max-width: 430px;
      text-shadow: 0 2px 22px rgba(0, 0, 0, 0.6);
    }

    .eyebrow {
      display: flex;
      align-items: center;
      gap: 10px;
      margin-bottom: 12px;
      color: var(--cyan);
      font-size: 11px;
      font-weight: 700;
      letter-spacing: 0.24em;
      text-transform: uppercase;
    }

    .eyebrow::before {
      content: "";
      width: 28px;
      height: 1px;
      background: var(--cyan);
      box-shadow: 0 0 10px var(--cyan);
    }

    h1 {
      margin: 0;
      font-family: Georgia, "Times New Roman", serif;
      font-size: clamp(38px, 6vw, 76px);
      font-weight: 400;
      line-height: 0.94;
      letter-spacing: -0.035em;
    }

    .subtitle {
      max-width: 360px;
      margin: 18px 0 0;
      color: rgba(229, 240, 235, 0.68);
      font-size: clamp(13px, 1.5vw, 16px);
      line-height: 1.6;
    }

    .controls {
      position: absolute;
      top: clamp(24px, 5vw, 58px);
      right: clamp(24px, 5vw, 64px);
      display: flex;
      flex-direction: column;
      gap: 10px;
      pointer-events: auto;
    }

    button {
      appearance: none;
      border: 1px solid var(--border);
      border-radius: 999px;
      padding: 10px 15px;
      color: rgba(237, 248, 244, 0.86);
      background: var(--panel);
      backdrop-filter: blur(14px);
      -webkit-backdrop-filter: blur(14px);
      font: inherit;
      font-size: 12px;
      letter-spacing: 0.04em;
      cursor: pointer;
      transition: 160ms ease;
    }

    button:hover {
      color: white;
      border-color: rgba(118, 231, 223, 0.65);
      background: rgba(18, 43, 48, 0.85);
      transform: translateY(-1px);
    }

    button.active {
      color: #071316;
      border-color: var(--cyan);
      background: var(--cyan);
    }

    .legend {
      position: absolute;
      left: clamp(24px, 5vw, 72px);
      bottom: clamp(24px, 5vw, 58px);
      display: flex;
      align-items: center;
      gap: 12px;
      color: rgba(225, 240, 235, 0.58);
      font-size: 11px;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    .mouse {
      position: relative;
      width: 17px;
      height: 25px;
      border: 1px solid rgba(227, 182, 109, 0.65);
      border-radius: 9px;
    }

    .mouse::after {
      content: "";
      position: absolute;
      top: 5px;
      left: 7px;
      width: 2px;
      height: 5px;
      border-radius: 2px;
      background: var(--gold);
      animation: scroll 1.8s ease-in-out infinite;
    }

    @keyframes scroll {
      0%, 100% { transform: translateY(0); opacity: 0.35; }
      50% { transform: translateY(5px); opacity: 1; }
    }

    .tooltip {
      position: fixed;
      z-index: 5;
      display: none;
      padding: 9px 12px;
      border: 1px solid rgba(227, 182, 109, 0.45);
      border-radius: 8px;
      color: #fff0cf;
      background: rgba(8, 18, 23, 0.92);
      box-shadow: 0 10px 35px rgba(0, 0, 0, 0.45);
      font-size: 12px;
      pointer-events: none;
      transform: translate(14px, 14px);
    }

    .tooltip::after {
      content: "";
      position: absolute;
      left: -18px;
      top: 50%;
      width: 15px;
      height: 1px;
      background: rgba(227, 182, 109, 0.7);
    }

    .tooltip.show {
      display: block;
    }

    .credit {
      position: absolute;
      right: clamp(24px, 5vw, 64px);
      bottom: clamp(24px, 5vw, 58px);
      color: rgba(225, 240, 235, 0.35);
      font-size: 10px;
      letter-spacing: 0.16em;
      text-transform: uppercase;
    }

    @media (max-width: 700px) {
      .subtitle {
        max-width: 280px;
      }

      .controls {
        top: auto;
        right: 18px;
        bottom: 66px;
        flex-direction: row;
      }

      button {
        padding: 9px 11px;
        font-size: 10px;
      }

      .legend {
        bottom: 25px;
      }

      .credit {
        display: none;
      }
    }
  </style>
</head>

<body>
  <div class="vignette"></div>

  <div class="hud">
    <section class="title-block">
      <div class="eyebrow">Artifact of the Walking Brigade</div>
      <h1>Dawnbreaker<br />Kite Shield</h1>
      <p class="subtitle">
        A celestial steel shield, bound in aged brass and crowned with the
        sunward boss of its first adventurer.
      </p>
    </section>

    <nav class="controls" aria-label="Scene controls">
      <button id="rotateButton" type="button">Auto orbit</button>
      <button id="bossButton" type="button">Inspect central boss</button>
      <button id="chargeButton" type="button">Charge emblem</button>
    </nav>

    <div class="legend">
      <span class="mouse"></span>
      <span>Drag to orbit · Scroll or pinch to zoom</span>
    </div>

    <div class="credit">Three.js core · procedural scene</div>
  </div>

  <div id="tooltip" class="tooltip">Celestial sun boss</div>

  <script type="module">
    import * as THREE from
      "https://cdnjs.cloudflare.com/ajax/libs/three.js/0.160.0/three.module.min.js";

    // ------------------------------------------------------------
    // Renderer and scene
    // ------------------------------------------------------------

    const renderer = new THREE.WebGLRenderer({
      antialias: true,
      powerPreference: "high-performance"
    });

    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.15;
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;

    renderer.domElement.tabIndex = 0;
    renderer.domElement.setAttribute(
      "aria-label",
      "Interactive three-dimensional adventurer's kite shield"
    );
    document.body.prepend(renderer.domElement);

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x071018);
    scene.fog = new THREE.FogExp2(0x071018, 0.035);

    const camera = new THREE.PerspectiveCamera(
      38,
      window.innerWidth / window.innerHeight,
      0.1,
      100
    );

    const clock = new THREE.Clock();

    // ------------------------------------------------------------
    // Materials
    // ------------------------------------------------------------

    const shieldMaterial = new THREE.MeshPhysicalMaterial({
      color: 0x214b49,
      metalness: 0.78,
      roughness: 0.27,
      clearcoat: 0.42,
      clearcoatRoughness: 0.25
    });

    const innerPlateMaterial = new THREE.MeshStandardMaterial({
      color: 0x122d30,
      metalness: 0.82,
      roughness: 0.34
    });

    const brassMaterial = new THREE.MeshStandardMaterial({
      color: 0xc8974b,
      metalness: 0.9,
      roughness: 0.24
    });

    const darkBrassMaterial = new THREE.MeshStandardMaterial({
      color: 0x765326,
      metalness: 0.86,
      roughness: 0.32
    });

    const leatherMaterial = new THREE.MeshStandardMaterial({
      color: 0x281612,
      metalness: 0.05,
      roughness: 0.88
    });

    const seamMaterial = new THREE.MeshStandardMaterial({
      color: 0x66401e,
      metalness: 0.5,
      roughness: 0.55
    });

    const bossFaceMaterial = new THREE.MeshStandardMaterial({
      color: 0x9ab6ad,
      metalness: 0.72,
      roughness: 0.28,
      emissive: 0x071b19,
      emissiveIntensity: 0.55
    });

    const sunMaterial = new THREE.MeshStandardMaterial({
      color: 0xffd27b,
      metalness: 0.35,
      roughness: 0.22,
      emissive: 0xff8b32,
      emissiveIntensity: 1.15
    });

    const scanMaterial = new THREE.MeshBasicMaterial({
      color: 0x76f1e4,
      transparent: true,
      opacity: 0.28,
      depthWrite: false,
      side: THREE.DoubleSide
    });

    // ------------------------------------------------------------
    // Lighting
    // ------------------------------------------------------------

    scene.add(new THREE.HemisphereLight(0x9adfff, 0x17100b, 1.55));

    const keyLight = new THREE.DirectionalLight(0xffd7a0, 3.4);
    keyLight.position.set(4.5, 6.5, 6);
    keyLight.castShadow = true;
    keyLight.shadow.mapSize.set(2048, 2048);
    keyLight.shadow.camera.near = 0.5;
    keyLight.shadow.camera.far = 20;
    keyLight.shadow.camera.left = -5;
    keyLight.shadow.camera.right = 5;
    keyLight.shadow.camera.top = 5;
    keyLight.shadow.camera.bottom = -5;
    keyLight.shadow.bias = -0.0004;
    scene.add(keyLight);

    const rimLight = new THREE.DirectionalLight(0x4edfff, 2.4);
    rimLight.position.set(-5, 1.5, 4);
    scene.add(rimLight);

    const warmLight = new THREE.PointLight(0xff8a3d, 28, 12, 2);
    warmLight.position.set(3.5, -1.5, 3);
    scene.add(warmLight);

    const cyanLight = new THREE.PointLight(0x50e8df, 22, 10, 2);
    cyanLight.position.set(-3, 2, 2);
    scene.add(cyanLight);

    // ------------------------------------------------------------
    // Display pedestal and floor
    // ------------------------------------------------------------

    const floor = new THREE.Mesh(
      new THREE.PlaneGeometry(40, 40),
      new THREE.MeshStandardMaterial({
        color: 0x091319,
        metalness: 0.22,
        roughness: 0.88
      })
    );
    floor.rotation.x = -Math.PI / 2;
    floor.position.y = -2.05;
    floor.receiveShadow = true;
    scene.add(floor);

    const pedestal = new THREE.Mesh(
      new THREE.CylinderGeometry(3.15, 3.45, 0.24, 80),
      new THREE.MeshStandardMaterial({
        color: 0x101c21,
        metalness: 0.65,
        roughness: 0.48
      })
    );
    pedestal.position.y = -1.92;
    pedestal.receiveShadow = true;
    pedestal.castShadow = true;
    scene.add(pedestal);

    const pedestalRim = new THREE.Mesh(
      new THREE.TorusGeometry(2.86, 0.028, 8, 100),
      new THREE.MeshBasicMaterial({
        color: 0x63a99e,
        transparent: true,
        opacity: 0.45
      })
    );
    pedestalRim.rotation.x = Math.PI / 2;
    pedestalRim.position.y = -1.79;
    scene.add(pedestalRim);

    // ------------------------------------------------------------
    // Kite-shaped shield
    // ------------------------------------------------------------

    const shieldGroup = new THREE.Group();
    shieldGroup.position.y = 0.18;
    shieldGroup.rotation.y = -0.13;
    scene.add(shieldGroup);

    const shieldShape = new THREE.Shape();
    shieldShape.moveTo(-1.65, -0.82);
    shieldShape.lineTo(1.65, -1.15);
    shieldShape.lineTo(1.65, 0.88);
    shieldShape.lineTo(-1.65, 1.12);
    shieldShape.closePath();

    const shieldGeometry = new THREE.ExtrudeGeometry(shieldShape, {
      depth: 0.18,
      bevelEnabled: true,
      bevelSegments: 4,
      steps: 1,
      bevelSize: 0.075,
      bevelThickness: 0.065,
      curveSegments: 2
    });
    shieldGeometry.translate(0, 0, -0.09);

    const shieldBody = new THREE.Mesh(shieldGeometry, shieldMaterial);
    shieldBody.castShadow = true;
    shieldBody.receiveShadow = true;
    shieldGroup.add(shieldBody);

    const innerGeometry = shieldGeometry.clone();
    innerGeometry.scale(0.88, 0.88, 1);

    const innerPlate = new THREE.Mesh(innerGeometry, innerPlateMaterial);
    innerPlate.position.z = 0.145;
    innerPlate.castShadow = true;
    shieldGroup.add(innerPlate);

    // Rounded brass perimeter.
    const shieldPoints = shieldShape.getPoints(5);
    const rimCurve = new THREE.CatmullRomCurve3(
      shieldPoints.map((point) => new THREE.Vector3(point.x, point.y, 0.17)),
      true,
      "centripetal"
    );

    const rim = new THREE.Mesh(
      new THREE.TubeGeometry(rimCurve, 180, 0.075, 8, true),
      brassMaterial
    );
    rim.castShadow = true;
    shieldGroup.add(rim);

    // Fine inner perimeter line.
    const innerRimCurve = new THREE.CatmullRomCurve3(
      shieldPoints
        .map((point) => new THREE.Vector3(point.x * 0.82, point.y * 0.82, 0.205))
        .slice(0, -1),
      true,
      "centripetal"
    );

    const innerRim = new THREE.Mesh(
      new THREE.TubeGeometry(innerRimCurve, 150, 0.018, 6, true),
      darkBrassMaterial
    );
    shieldGroup.add(innerRim);

    // Decorative vertical inlays.
    for (const x of [-0.67, 0.67]) {
      const inlay = new THREE.Mesh(
        new THREE.BoxGeometry(0.035, 1.55, 0.035),
        darkBrassMaterial
      );
      inlay.position.set(x, 0.02, 0.205);
      shieldGroup.add(inlay);
    }

    // Leather grip and metal mounts behind the shield.
    const grip = new THREE.Mesh(
      new THREE.BoxGeometry(0.25, 1.8, 0.13),
      leatherMaterial
    );
    grip.position.set(0, -0.05, -0.29);
    grip.castShadow = true;
    shieldGroup.add(grip);

    for (const y of [-0.78, 0.72]) {
      const mount = new THREE.Mesh(
        new THREE.BoxGeometry(0.4, 0.16, 0.18),
        darkBrassMaterial
      );
      mount.position.set(0, y, -0.24);
      mount.castShadow = true;
      shieldGroup.add(mount);

      const rivet = new THREE.Mesh(
        new THREE.CylinderGeometry(0.075, 0.075, 0.035, 16),
        brassMaterial
      );
      rivet.rotation.x = Math.PI / 2;
      rivet.position.set(0, y, -0.35);
      shieldGroup.add(rivet);
    }

    // Border rivets.
    const rivetGeometry = new THREE.SphereGeometry(0.055, 10, 8);
    const rivetLocations = rimCurve.getPoints(120);

    for (let i = 0; i < rivetLocations.length; i += 3) {
      const point = rivetLocations[i];
      const rivet = new THREE.Mesh(rivetGeometry, brassMaterial);
      rivet.position.set(point.x, point.y, 0.22);
      rivet.castShadow = true;
      shieldGroup.add(rivet);
    }

    // Corner bosses.
    const cornerGeometry = new THREE.OctahedronGeometry(0.16, 0);
    const corners = [
      [-1.52, -0.68],
      [1.52, -0.98],
      [1.52, 0.72],
      [-1.52, 1.02]
    ];

    for (const [x, y] of corners) {
      const cornerBoss = new THREE.Mesh(cornerGeometry, brassMaterial);
      cornerBoss.position.set(x, y, 0.22);
      cornerBoss.scale.z = 0.45;
      cornerBoss.castShadow = true;
      shieldGroup.add(cornerBoss);
    }

    // ------------------------------------------------------------
    // Central raised boss
    // ------------------------------------------------------------

    const bossGroup = new THREE.Group();
    bossGroup.position.set(0, 0.02, 0.28);
    shieldGroup.add(bossGroup);

    const bossBack = new THREE.Mesh(
      new THREE.CylinderGeometry(0.79, 0.79, 0.16, 72),
      innerPlateMaterial
    );
    bossBack.rotation.x = Math.PI / 2;
    bossBack.castShadow = true;
    bossGroup.add(bossBack);

    const bossOuterRing = new THREE.Mesh(
      new THREE.TorusGeometry(0.735, 0.095, 12, 80),
      brassMaterial
    );
    bossOuterRing.position.z = 0.08;
    bossOuterRing.castShadow = true;
    bossGroup.add(bossOuterRing);

    const bossFace = new THREE.Mesh(
      new THREE.CylinderGeometry(0.615, 0.615, 0.12, 72),
      bossFaceMaterial
    );
    bossFace.rotation.x = Math.PI / 2;
    bossFace.position.z = 0.16;
    bossFace.castShadow = true;
    bossGroup.add(bossFace);

    const bossFaceRing = new THREE.Mesh(
      new THREE.TorusGeometry(0.55, 0.035, 8, 72),
      darkBrassMaterial
    );
    bossFaceRing.position.z = 0.235;
    bossGroup.add(bossFaceRing);

    // Crossed heraldic bars.
    const barA = new THREE.Mesh(
      new THREE.BoxGeometry(0.43, 0.065, 0.06),
      brassMaterial
    );
    barA.position.z = 0.255;
    bossGroup.add(barA);

    const barB = new THREE.Mesh(
      new THREE.BoxGeometry(0.065, 0.43, 0.06),
      brassMaterial
    );
    barB.position.z = 0.255;
    bossGroup.add(barB);

    // Radiant sun disc.
    const sunDisc = new THREE.Mesh(
      new THREE.CircleGeometry(0.255, 48),
      sunMaterial
    );
    sunDisc.position.z = 0.31;
    bossGroup.add(sunDisc);

    const sunCore = new THREE.Mesh(
      new THREE.SphereGeometry(0.09, 20, 16),
      new THREE.MeshStandardMaterial({
        color: 0xffe6a8,
        emissive: 0xff7b20,
        emissiveIntensity: 1.6,
        metalness: 0.2,
        roughness: 0.2
      })
    );
    sunCore.position.z = 0.34;
    bossGroup.add(sunCore);

    // Twelve radial spikes surrounding the boss.
    const spikeGeometry = new THREE.ConeGeometry(0.115, 0.48, 5);
    const spikeMaterial = brassMaterial;

    for (let i = 0; i < 12; i++) {
      const angle = (i / 12) * Math.PI * 2;
      const spike = new THREE.Mesh(spikeGeometry, spikeMaterial);
      const radius = 0.84;

      spike.position.set(
        Math.cos(angle) * radius,
        Math.sin(angle) * radius,
        0.31
      );

      // Local cone tip points along +Y; rotate it radially outward.
      spike.rotation.z = angle - Math.PI / 2;
      spike.rotation.x = Math.sin(angle) * 0.12;
      spike.rotation.y = -Math.cos(angle) * 0.12;
      spike.castShadow = true;
      bossGroup.add(spike);
    }

    // Expanding scan ring around the boss.
    const scanRing = new THREE.Mesh(
      new THREE.RingGeometry(0.91, 0.975, 72),
      scanMaterial
    );
    scanRing.position.z = 0.38;
    bossGroup.add(scanRing);

    // Charge shockwave.
    const chargeRing = new THREE.Mesh(
      new THREE.RingGeometry(1.01, 1.045, 72),
      new THREE.MeshBasicMaterial({
        color: 0x7affed,
        transparent: true,
        opacity: 0,
        depthWrite: false,
        side: THREE.DoubleSide
      })
    );
    chargeRing.position.z = 0.4;
    bossGroup.add(chargeRing);

    // ------------------------------------------------------------
    // Floating particles
    // ------------------------------------------------------------

    const particleCount = 150;
    const particlePositions = new Float32Array(particleCount * 3);
    const particleBase = new Float32Array(particleCount * 3);

    for (let i = 0; i < particleCount; i++) {
      const offset = i * 3;
      particleBase[offset] = (Math.random() - 0.5) * 13;
      particleBase[offset + 1] = (Math.random() - 0.5) * 8 - 1.5;
      particleBase[offset + 2] = (Math.random() - 0.5) * 9;
      particlePositions.set(particleBase.slice(offset, offset + 3), offset);
    }

    const particleGeometry = new THREE.BufferGeometry();
    particleGeometry.setAttribute(
      "position",
      new THREE.BufferAttribute(particlePositions, 3)
    );

    const particles = new THREE.Points(
      particleGeometry,
      new THREE.PointsMaterial({
        color: 0x8de9df,
        size: 0.025,
        transparent: true,
        opacity: 0.55,
        depthWrite: false,
        blending: THREE.AdditiveBlending
      })
    );
    scene.add(particles);

    // ------------------------------------------------------------
    // Custom camera controls — no external controls addon
    // ------------------------------------------------------------

    const cameraTarget = new THREE.Vector3(0, 0.12, 0);
    const spherical = new THREE.Spherical(8.4, 1.25, 0.32);

    function updateCamera() {
      camera.position.setFromSpherical(spherical).add(cameraTarget);
      camera.lookAt(cameraTarget);
    }

    updateCamera();

    const pointers = new Map();
    let dragDistance = 0;
    let dragAge = 0;
    let lastPinchDistance = 0;
    let autoRotate = false;
    let bossPulse = 0;

    const canvas = renderer.domElement;

    canvas.addEventListener("pointerdown", (event) => {
      if (event.button !== 0) return;

      canvas.focus({ preventScroll: true });
      canvas.setPointerCapture(event.pointerId);
      pointers.set(event.pointerId, {
        x: event.clientX,
        y: event.clientY
      });

      dragDistance = 0;
      dragAge = 0;
      canvas.classList.add("dragging");
    });

    canvas.addEventListener("pointermove", (event) => {
      const previous = pointers.get(event.pointerId);
      if (!previous) return;

      const dx = event.clientX - previous.x;
      const dy = event.clientY - previous.y;

      pointers.set(event.pointerId, {
        x: event.clientX,
        y: event.clientY
      });

      dragDistance += Math.abs(dx) + Math.abs(dy);
      dragAge = 0;

      if (pointers.size === 1) {
        spherical.theta -= dx * 0.006;
        spherical.phi = THREE.MathUtils.clamp(
          spherical.phi - dy * 0.005,
          0.45,
          2.45
        );
      } else if (pointers.size === 2) {
        const points = [...pointers.values()];
        const distance = Math.hypot(
          points[0].x - points[1].x,
          points[0].y - points[1].y
        );

        if (lastPinchDistance > 0) {
          spherical.radius = THREE.MathUtils.clamp(
            spherical.radius * (lastPinchDistance / distance),
            4.7,
            14
          );
        }

        lastPinchDistance = distance;
      }

      updateCamera();
    });

    const raycaster = new THREE.Raycaster();
    const pointerNDC = new THREE.Vector2();

    function handleShieldClick(event) {
      const rect = canvas.getBoundingClientRect();

      pointerNDC.x =
        ((event.clientX - rect.left) / rect.width) * 2 - 1;
      pointerNDC.y =
        -((event.clientY - rect.top) / rect.height) * 2 + 1;

      raycaster.setFromCamera(pointerNDC, camera);
      const hits = raycaster.intersectObject(shieldBody, false);

      if (hits.length > 0) {
        bossPulse = 1;
        tooltip.classList.add("show");
        tooltip.style.left = `${event.clientX}px`;
        tooltip.style.top = `${event.clientY}px`;
      }
    }

    canvas.addEventListener("pointerup", (event) => {
      const wasSinglePointer = pointers.size === 1;

      if (wasSinglePointer && dragDistance < 6) {
        handleShieldClick(event);
      }

      pointers.delete(event.pointerId);
      dragAge = 0;

      if (pointers.size < 2) {
        lastPinchDistance = 0;
      }

      if (pointers.size === 0) {
        canvas.classList.remove("dragging");
      }
    });

    canvas.addEventListener("pointercancel", (event) => {
      pointers.delete(event.pointerId);
      dragAge = 0;
      canvas.classList.remove("dragging");
    });

    canvas.addEventListener(
      "wheel",
      (event) => {
        event.preventDefault();
        spherical.radius = THREE.MathUtils.clamp(
          spherical.radius * Math.exp(event.deltaY * 0.001),
          4.7,
          14
        );
        updateCamera();
      },
      { passive: false }
    );

    canvas.addEventListener("dblclick", resetView);

    window.addEventListener("keydown", (event) => {
      const key = event.key.toLowerCase();

      if (key === "arrowleft") spherical.theta += 0.12;
      else if (key === "arrowright") spherical.theta -= 0.12;
      else if (key === "arrowup") spherical.phi -= 0.08;
      else if (key === "arrowdown") spherical.phi += 0.08;
      else if (key === "+" || key === "=") spherical.radius *= 0.9;
      else if (key === "-") spherical.radius *= 1.1;
      else return;

      spherical.phi = THREE.MathUtils.clamp(spherical.phi, 0.45, 2.45);
      spherical.radius = THREE.MathUtils.clamp(spherical.radius, 4.7, 14);
      updateCamera();
    });

    function resetView() {
      cameraTarget.set(0, 0.12, 0);
      spherical.set(8.4, 1.25, 0.32);
      updateCamera();
    }

    const rotateButton = document.getElementById("rotateButton");
    const bossButton = document.getElementById("bossButton");
    const chargeButton = document.getElementById("chargeButton");
    const tooltip = document.getElementById("tooltip");

    rotateButton.addEventListener("click", () => {
      autoRotate = !autoRotate;
      rotateButton.classList.toggle("active", autoRotate);
      rotateButton.textContent = autoRotate ? "Pause orbit" : "Auto orbit";
    });

    bossButton.addEventListener("click", () => {
      cameraTarget.set(0, 0.16, 0.35);
      spherical.set(5.1, 1.35, 0.12);
      updateCamera();
    });

    chargeButton.addEventListener("click", () => {
      bossPulse = 1;
      chargeButton.classList.add("active");
      chargeButton.textContent = "Emblem charged";
      tooltip.classList.add("show");
      tooltip.style.left = `${window.innerWidth / 2}px`;
      tooltip.style.top = `${window.innerHeight / 2}px`;
    });

    // ------------------------------------------------------------
    // Resize and animation
    // ------------------------------------------------------------

    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      renderer.setSize(window.innerWidth, window.innerHeight);
    });

    function animate() {
      requestAnimationFrame(animate);

      const delta = Math.min(clock.getDelta(), 0.05);
      const elapsed = clock.elapsedTime;

      if (autoRotate && pointers.size === 0 && dragAge > 1.5) {
        spherical.theta += delta * 0.12;
        updateCamera();
      }

      // Gentle floating motion.
      shieldGroup.position.y = 0.18 + Math.sin(elapsed * 1.35) * 0.075;
      shieldGroup.rotation.y = -0.13 + Math.sin(elapsed * 0.42) * 0.025;

      // Boss breathing and slow ceremonial rotation.
      bossGroup.rotation.z = Math.sin(elapsed * 0.55) * 0.018;
      bossGroup.rotation.y = Math.sin(elapsed * 0.32) * 0.025;

      const pulseEnvelope = Math.exp(-delta * 1.5);
      bossPulse = Math.max(0, bossPulse - delta * 1.35);

      sunMaterial.emissiveIntensity = 1.15 + bossPulse * 1.8;
      bossFaceMaterial.emissiveIntensity = 0.55 + bossPulse * 0.7;

      scanMaterial.opacity = 0.2 + bossPulse * 0.45;
      scanRing.scale.setScalar(1 + Math.sin(elapsed * 2.4) * 0.025);

      if (bossPulse > 0) {
        chargeRing.visible = true;
        const chargePhase = 1 - bossPulse * 18;
        chargeRing.scale.setScalar(1 + chargePhase * 4.5);
        chargeMaterial = chargeRing.material;
        chargeMaterial.opacity = chargePhase * 0.8;
      } else {
        chargeRing.visible = false;
      }

      // Animate suspended motes.
      const positions = particleGeometry.attributes.position.array;

      for (let i = 0; i < particleCount; i++) {
        const offset = i * 3;
        positions[offset] =
          particleBase[offset] + Math.sin(elapsed * 0.35 + i * 0.71) * 0.16;
        positions[offset + 1] =
          particleBase[offset + 1] + Math.sin(elapsed * 0.55 + i) * 0.12;
        positions[offset + 2] =
          particleBase[offset + 2] + Math.cos(elapsed * 0.28 + i * 0.43) * 0.1;
      }

      particleGeometry.attributes.position.needsUpdate = true;

      renderer.render(scene, camera);
    }

    animate();
  </script>
